def compute(vars):
    gross_profit = vars["Gross Profit"]
    revenue = vars["Revenue"]

    if gross_profit is None or revenue is None:
        return {
            "value": None,
            "trace": {
                "Gross Profit": gross_profit,
                "Revenue": revenue,
                "Cost of Sales": None,
                "output_meta": {
                    "currency": "USD",
                    "scale": "million",
                    "unit": None
                }
            }
        }

    cost_of_sales = revenue - gross_profit

    return {
        "value": cost_of_sales,
        "trace": {
            "Gross Profit": gross_profit,
            "Revenue": revenue,
            "Cost of Sales": cost_of_sales,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
